CREATE TABLE `level_resources` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `level_id` int(11) NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `resource_type` enum('video','pdf','article','interactive','quiz','audio') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'video',
  `resource_lang` enum('ar','en','mixed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ar',
  `url` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_external` tinyint(1) NOT NULL DEFAULT '1',
  `duration_label` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'e.g. 12 ╪»┘é┘è┘é╪⌐ ╪ú┘ê 45 ╪╡┘ü╪¡╪⌐',
  `thumbnail_url` text COLLATE utf8mb4_unicode_ci,
  `author_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` int(11) NOT NULL DEFAULT '0',
  `is_featured` tinyint(1) NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `view_count` int(11) NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_level_active` (`level_id`,`is_active`),
  KEY `idx_level_type` (`level_id`,`resource_type`)
) ENGINE=InnoDB AUTO_INCREMENT=39 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
