CREATE TABLE `recommended_courses` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `level_id` int(11) NOT NULL,
  `topic_keyword` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `instructor` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `youtube_id` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `youtube_url` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `playlist_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `duration` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content_type` enum('targeted_video','full_playlist','hands_on_lab') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'targeted_video',
  `badge_text` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_courses_level` (`level_id`),
  CONSTRAINT `fk_courses_level` FOREIGN KEY (`level_id`) REFERENCES `levels` (`id`) ON DELETE CASCADE
