  `current_level_id` int(11) NOT NULL DEFAULT '1',
  `highest_mastered_level_id` int(11) NOT NULL DEFAULT '1',
  `remediation_status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'clear',
  `must_change_password` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`),
  KEY `fk_users_level` (`current_level_id`),
  CONSTRAINT `fk_users_level` FOREIGN KEY (`current_level_id`) REFERENCES `levels` (`id`)
